package com.genchat.service;
import com.genchat.model.User; import com.genchat.repository.UserRepository; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import org.springframework.security.crypto.password.PasswordEncoder; import static org.junit.jupiter.api.Assertions.*;
class UserServiceTest { @Test void registerHashesPassword(){UserRepository repo=Mockito.mock(UserRepository.class); PasswordEncoder enc=Mockito.mock(PasswordEncoder.class); Mockito.when(repo.findByUsername("hema")).thenReturn(java.util.Optional.empty()); Mockito.when(enc.encode("1234")).thenReturn("HASH"); Mockito.when(repo.save(Mockito.any(User.class))).thenAnswer(i->i.getArgument(0)); User u=new UserService(repo,enc).register("hema","1234"); assertEquals("hema",u.getUsername()); assertEquals("HASH",u.getPassword());} }
